{
 "research_concepts": [
  "PNR (Pick and Roll) efficiency",
  "DRIVE (Drive play type)",
  "Points Per Possession (PPP)",
  "Play sequence analysis",
  "Contextual effects on play efficiency",
  "Play-type labeling quality"
 ],
 "methodological_questions": [
  "How to define a 'preceding' action in a play sequence?",
  "How to control for confounding factors in play efficiency analysis (e.g., player skill, defense, game state)?",
  "What is the reliability of automated play-type labeling for DRIVE and PNR?",
  "What is the appropriate unit of analysis for measuring the impact of a preceding action on a subsequent play's efficiency?",
  "Sample size and power considerations for detecting effects of specific play sequences.",
  "How to account for potential labeling errors and artifacts in derived play types?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "DRIVE PPP is stable or improves across playoff series, and PNR PPP improves (+0.087), not declines as hypothesized."
  },
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20, indicating a labeling artifact."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE PPP is materially higher in Regular Season (1.198) than Playoffs (0.912, -0.286), and PNR PPP also declines (-0.173)."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "OTHER play type PPP is inflated by 36% foul endings; DRIVE PPP is 12 percentage points below its foul benchmark (FOUL_LEAK); PNR shows 22% foul rate. Only 0.7% of possessions map to a real play type via initiation_type."
  },
  {
   "id": "FAM:SF-APPS-014",
   "status_as_recorded": "rejected",
   "finding": "DRIVE efficiency rises early-to-late within a game (+0.078 in Game 1, +0.093 across all games) instead of dropping."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Observational study on whether a specific opponent play type on the preceding possession suppresses each star's next-possession PPP. PUTBACK is a top suppressor for several stars."
  },
  {
   "id": "FAM:SF07",
   "status_as_recorded": "supported",
   "finding": "After the opponent runs play type X, the next offensive play type Y scores above Y's unconditional H2 baseline, demonstrating a 'defensive aftershock' where all 8 play types show a PPP increase."
  },
  {
   "id": "FAM:SF-APPM-058",
   "status_as_recorded": "not a hypothesis test",
   "finding": "PNR shot-level season rates vary by team (e.g., OKC 7.567% to IND 13.824% of half-court shots), serving as a calibration input rather than a hypothesis test."
  },
  {
   "id": "FAM:SF-APPS-012",
   "status_as_recorded": "not a hypothesis test",
   "finding": "DRIVE allowed PPP decreases from Regular Season (1.191) to Playoffs (0.923), and its share declines, while PNR PPP also decreases but its share increases significantly (+12.1pp), potentially due to tagging differences."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Overall audit FAIL for inferred play-type labels: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail, indicating systematic issues with labels."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-010",
   "what_failed": "Assessing play-type PPP change across playoff series game buckets",
   "why": "LIM:selection_or_regression_to_the_mean"
  },
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Assuming possession-level play types from PBP contain unbiased predictive structure for SPOT_UP and TRANSITION",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to assisted flag existing only on makes"
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Assuming play-type PPP differences are real efficiency, not labeling/foul artifacts",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to OTHER PPP inflation by foul endings and DRIVE foul leakage"
  },
  {
   "id": "FAM:SF-APPA-050",
   "what_failed": "Analyzing sequential suppression effects without multiplicity correction and with small sample sizes for specific cells",
   "why": "E_unclear (mechanism unclear from the records) and LIM:small_sample"
  },
  {
   "id": "FAM:SF07",
   "what_failed": "Analyzing specific sequential pair premiums",
   "why": "LIM:small_sample for some specific pairs"
  },
  {
   "id": "FAM:SF-APPS-012",
   "what_failed": "Describing defensive PPP allowed and possession share, RS vs playoffs, without inferential tests",
   "why": "E_unclear (mechanism unclear from the records); PNR share jump may reflect tagging differences"
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Auditing play-type label accuracy and distribution",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:label_or_classification_error; LIM:leakage; LIM:small_sample"
  }
 ],
 "evidence_establishes": [
  "Play-type PPP can vary significantly by context (e.g., Regular Season vs. Playoffs), as shown for DRIVE and PNR (FAM:SF-APPS-011).",
  "Automated play-type labeling has historically suffered from significant artifacts and errors, leading to inflated or deflated PPP values for certain play types (FAM:SF-PAP-096, FAM:SF-CHT-025, FAM:SF-APPM-014). Specifically, DRIVE labels have shown foul leakage and PPP below benchmarks, and PNR labels may have tagging differences (FAM:SF-CHT-025, FAM:SF-APPS-012, FAM:SF-APPM-014).",
  "Sequential play effects on PPP can exist and be measurable, as demonstrated by 'defensive aftershock' where offensive play types score above baseline after an opponent's play (FAM:SF07).",
  "Small sample sizes and lack of multiplicity correction are common limitations in sequential play analysis (FAM:SF-APPA-050, FAM:SF07)."
 ],
 "evidence_does_not_establish": [
  "Whether a teammate DRIVE specifically preceding a PNR consistently raises PNR PPP.",
  "The current state of play-type labeling quality for DRIVE and PNR after the identified artifacts and failures (FAM:SF-PAP-096, FAM:SF-CHT-025, FAM:SF-APPM-014) have been addressed or if they persist.",
  "The magnitude or consistency of 'teammate' sequential effects, as existing evidence focuses on opponent plays (FAM:SF07, FAM:SF-APPA-050).",
  "A robust methodology for defining 'preceding' action in a way that isolates the causal effect without confounding factors specific to teammate interactions."
 ],
 "own_inferences": [
  "The research question requires a precise definition of 'preceding' and 'teammate DRIVE' within a possession or sequence of possessions.",
  "The historical issues with play-type labeling, especially for DRIVE and PNR, suggest that any observed effect could be an artifact of labeling rather than a genuine on-court phenomenon.",
  "Controlling for confounding factors like player skill, defensive coverage, and game state will be crucial to attribute any PPP change to the preceding DRIVE rather than other variables.",
  "The project's history of identifying and sometimes correcting labeling issues (e.g., FAM:SF-PAP-096) implies that the currently available derived play-type data might be an improvement over the data used in earlier failed audits, but this is not explicitly stated."
 ],
 "uncertainties": [
  "The current reliability and accuracy of the 'DRIVE' and 'PNR' play-type labels in the derived possession records, given the past audit failures (FAM:SF-CHT-025, FAM:SF-APPM-014).",
  "How 'preceding' is defined in the available graph database (e.g., immediately preceding on the same possession, previous possession, within a certain time window).",
  "The frequency of the specific sequence 'teammate DRIVE preceding a PNR', which will impact sample size and statistical power.",
  "Whether the 'teammate DRIVE' is a *failed* drive or a *successful* drive, and how this distinction might affect the subsequent PNR PPP.",
  "The extent to which the graph database addresses the 'initiation_type' mapping issue (0.7% success rate in FAM:SF-CHT-025)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-CHT-025 and FAM:SF-APPM-014, highlights severe and systematic issues with the reliability of play-type labels, especially for DRIVE and PNR. This shifts the decision from a straightforward 'proceed' to 'do_not_proceed' without first addressing the data quality. While sequential effects are known to exist (FAM:SF07), the foundational data quality for the specific play types in question is too compromised to test the hypothesis reliably."
 },
 "testability": {
  "p_testable": 0.2,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "Historical audits indicate significant and systematic errors in play-type labeling for DRIVE and PNR, including foul leakage and low confidence labels (FAM:SF-CHT-025, FAM:SF-APPM-014). This directly undermines the reliability of PPP calculations for these play types."
   },
   {
    "code": "EXPOSURE_SPARSITY",
    "text": "The specific sequence 'teammate DRIVE preceding a PNR' is likely to be a rare event. Previous sequential studies noted small sample sizes for specific pairs (FAM:SF-APPA-050, FAM:SF07), indicating this could be a major limitation for power."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF07",
   "FAM:SF-APPA-050"
  ],
  "summary": "Previous research has established that sequential play effects exist and can influence the PPP of subsequent plays (FAM:SF07, FAM:SF-APPA-050). However, this work focused on opponent play types impacting a star's next possession or general 'defensive aftershock' for any next offensive play, not the specific effect of a teammate DRIVE on a subsequent PNR, nor has it addressed the significant labeling quality issues for DRIVE and PNR that would be prerequisite for such a study."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The primary risk is the unreliability of the 'DRIVE' and 'PNR' play-type labels themselves, as evidenced by multiple historical audits (FAM:SF-CHT-025, FAM:SF-APPM-014). If the labels are systematically flawed, any observed effect on PPP would be an artifact."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "The specific sequence 'teammate DRIVE preceding a PNR' may occur infrequently, leading to insufficient sample size for meaningful statistical inference and low power to detect any true effect."
  },
  {
   "code": "CONFOUNDING",
   "text": "Many factors could influence both the decision to execute a DRIVE and a subsequent PNR, as well as the PNR's efficiency. These include player skill, defensive scheme, game state, shot clock, and score differential. Without robust controls, any observed effect could be confounded by these variables."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "If this is part of a broader exploration of sequential play types, the risk of false positives due to multiple comparisons will increase, as noted in FAM:SF-APPA-050."
  },
  {
   "code": "RTM_SELECTION",
   "text": "The decision to run a DRIVE (especially if it's a failed or partially successful one) and then a PNR might not be random. Selection bias could lead to regression to the mean effects if, for example, a team runs a PNR after a 'bad' DRIVE, and the PNR PPP naturally reverts to the mean."
  }
 ],
 "predicted_outcome": {
  "supported": 0.1,
  "rejected": 0.1,
  "untestable": 0.4,
  "artifact": 0.3,
  "uncertain": 0.1
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The average difference in Points Per Possession (PPP) for PNR possessions that are immediately preceded by a teammate DRIVE (treatment group) compared to PNR possessions not immediately preceded by a teammate DRIVE (control group), within the same team and game context.",
  "unit": "Possession (specifically, the PNR possession).",
  "sample": "All PNR possessions from NBA 2022-23, 2023-24, 2024-25 regular seasons and playoffs, and 2025-26 regular season (complete). Filter for PNR possessions that are immediately preceded by a teammate DRIVE (treatment) and those that are not (control). Define 'teammate DRIVE preceding' as an offensive DRIVE action by any teammate (excluding the PNR initiator) that concludes within 5 seconds prior to the start of the PNR action within the same possession or immediately preceding possession, as recorded in the derived play-type graph database.",
  "power": "No power calculation is feasible without first assessing the sample size of the specific sequential event and validating the underlying play-type labels. If labels were validated, a target of detecting a 0.05 PPP difference with 80% power at alpha=0.05 would be a starting point.",
  "controls": "Match or control for confounding variables such as: PNR initiator, PNR screen setter, defensive matchup, game quarter, time remaining, score differential, and previous possession outcome. A mixed-effects model or propensity score matching could be employed, grouping by team and game to control for team-specific strategies and game-level variance.",
  "falsification": "A falsification test would involve checking if a 'teammate DRIVE' preceding a *random* play type (not PNR) also raises its PPP. If such a general effect is found, it would undermine the specificity of the hypothesis. Additionally, a rigorous audit of the 'DRIVE' and 'PNR' labels for accuracy and consistency (especially regarding foul rates and 'OTHER' leakage) is a prerequisite falsification of the data quality assumptions.",
  "multiplicity": "Given this is a single hypothesis, no specific multiplicity correction is immediately required. However, if this becomes part of a broader study of sequential play types, corrections (e.g., Bonferroni, FDR) would be necessary.",
  "decision_rule": "The hypothesis is supported if the mean PNR PPP for the treatment group is statistically significantly (p < 0.05) higher than the control group, after controlling for confounding factors, and provided that the underlying play-type labels for DRIVE and PNR are validated as reliable.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs; NBA 2025-26 regular season complete. Derived play-type possession records from the graph database, ensuring the latest version with any known label corrections applied."
 }

